//! Fixtures and assertions for uidiff tests.
const std = @import("std");
const values = @import("value.zig");
const regions = @import("diff/regions.zig");
const rows = @import("diff/rows.zig");
const canvas = @import("testing/canvas.zig");
const expect = @import("testing/expect.zig");

/// Region operations examined by comparison scenarios.
pub const region_rules = @import("testing/regions.zig");

/// Render-plan operations examined by sheet scenarios.
pub const sheet = @import("testing/sheet.zig");

/// Small arbitrary RGBA inputs generated by Smith.
pub const fuzz = @import("testing/fuzz.zig");

/// Painted screenshot fixture.
pub const Canvas = canvas.Canvas;
/// Fixture for moving adjacent row bands.
pub const RowExchange = canvas.RowExchange;
/// Opaque white for blank input screenshots.
pub const white = canvas.white;
/// Size of a default block edit.
pub const block_size = canvas.block_size;
/// Smallest changed-pixel support that can become a region.
pub const min_region_pixels = regions.min_region_pixels;
/// Initial grouping distance in CSS pixels.
pub const merge_gap = regions.merge_gap;
/// Row alignment's insertion and deletion budget.
pub const max_edits = rows.max_edits;

/// Mixes an ink colour over the canvas background.
pub const inkShade = canvas.inkShade;
/// Paints an antialiased diagonal at the given offset.
pub const diagonal = canvas.diagonal;
/// Paints distinct repeating bands.
pub const paintBands = canvas.paintBands;
/// Paints a page with optional stationary chrome and edits.
pub const auditPage = canvas.auditPage;
/// Paints a scrollable list of cards.
pub const fillCardList = canvas.fillCardList;
/// Paints one card and its label.
pub const paintCard = canvas.paintCard;
/// Paints the outline of the rounded panel fixture.
pub const strokeRounded = canvas.strokeRounded;
/// Checks that a region of the requested kind covers a point.
pub const hasRegion = expect.hasRegion;
/// Checks that a mark excludes a nearby edit body.
pub const hasSeparateMark = expect.hasSeparateMark;
/// Applies report padding to an expected region.
pub const paddedBox = expect.paddedBox;
/// Checks the geometry, kind and order of reported regions.
pub const checkRegions = expect.checkRegions;
/// Checks that a point is covered by an edit within the given width.
pub const expectEditAt = expect.expectEditAt;
/// Compares painted canvases using the public API.
pub const compareCanvases = expect.compareCanvases;
/// Checks the comparison against a list of expected regions.
pub const check = expect.check;
/// Checks an insertion and its reverse deletion.
pub const checkInsertion = expect.checkInsertion;
/// Checks the number of reported regions.
pub const count = expect.count;

/// Compares the full RGBA pixels of two runs.
pub fn sameRun(a: []const values.Pixel, b: []const values.Pixel) bool {
    return std.mem.eql(u8, std.mem.sliceAsBytes(a), std.mem.sliceAsBytes(b));
}
